#include <stdio.h>

int G[105][105];
int N, M;

int main(void) {
    scanf("%d %d", &N, &M);
    for (int i = 0; i < N; i++)
        for (int j = 0; j < M; j++)
            scanf("%d", &G[i][j]);

    /* Pattern A: required parity of cell (i,j) is (i+j) mod 2
       Pattern B: required parity is (i+j+1) mod 2 */
    long long costA = 0, costB = 0;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            int p = G[i][j] & 1;
            if (p != ((i + j) & 1)) costA++;
            else costB++;
        }
    }

    int useB = costB < costA;
    printf("%lld\n", costB < costA ? costB : costA);

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            int need = useB ? ((i + j + 1) & 1) : ((i + j) & 1);
            int v = G[i][j];
            if ((v & 1) != need) v++;
            printf("%d", v);
            if (j + 1 < M) printf(" ");
        }
        printf("\n");
    }
    return 0;
}
